## Code Example
```javascript
// Stream wrapper using useSyncExternalStore
function useAuditStream(tenantId) {
  const storeRef = useRef(null);
  if (!storeRef.current) {
    storeRef.current = createAuditStore(tenantId);
  }
  return useSyncExternalStore(
    storeRef.current.subscribe,
    storeRef.current.getSnapshot,
    storeRef.current.getServerSnapshot
  );
}

// Memoized selector keyed by (tenantId, timeWindow)
const selectBoundedEvents = memoize((tenantId, timeWindow) => {
  return (events) => {
    const cutoff = Date.now() - timeWindow;
    return events
      .filter(e => e.tenantId === tenantId && e.timestamp > cutoff)
      .slice(-120); // Bounded to 120 events
  };
});

// React.memo EventRow
const EventRow = memo(({ event }) => (
  <div>{event.action} - {event.timestamp}</div>
));

// Panel wiring
function AuditPanel({ tenantId }) {
  const events = useAuditStream(tenantId);
  const boundedEvents = useMemo(
    () => selectBoundedEvents(tenantId, 120000),
    [tenantId]
  )(events);

  return (
    <div>
      {boundedEvents.map(e => <EventRow key={e.id} event={e} />)}
    </div>
  );
}
```

## Why This Is Asked

This question tests practical streaming data handling in the browser: async iteration, backpressure management, error handling, and cancellation. It mirrors real-world applications that consume large event streams, logs, or real-time data feeds.

## Key Concepts

- **Fetch streaming responses** and ReadableStream APIs
- **NDJSON parsing** with line-by-line buffering
- **AsyncIterator** / for await...of syntax
- **Backpressure** with bounded queues (max 5 items)
- **AbortController** for cancellation and proper error propagation
- **Closures** to encapsulate internal state (buffer, reader, etc.)

## Code Example

```javascript
function createStreamingFetcher(url) {
  const controller = new AbortController();
  const buffer = [];
  let resolveNext;
  let rejectNext;

  const queue = new Promise((resolve, reject) => {
    resolveNext = resolve;
    rejectNext = reject;
  });

  async function start() {
    const response = await fetch(url, { signal: controller.signal });
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';

    while (true) {
      const { done, value } = await reader.read();
      if (done) {
        if (buffer.trim()) {
          try {
            resolveNext(JSON.parse(buffer));
          } catch (e) {
            rejectNext(new Error('Invalid NDJSON'));
          }
        }
        break;
      }

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop();

      for (const line of lines) {
        if (line.trim()) {
          try {
            resolveNext(JSON.parse(line));
          } catch (e) {
            rejectNext(new Error('Invalid NDJSON'));
          }
          if (buffer.length >= 5) {
            await queue;
          }
        }
      }
    }
  }

  start().catch(e => rejectNext(e));

  return {
    stream: {
      [Symbol.asyncIterator]() {
        return {
          next() {
            return queue.then(v => ({ value: v, done: false }));
          }
        };
      }
    },
    cancel: () => controller.abort()
  };
}
```

